\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 1258 (NT-051). CC BY 4.0. \url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Jeffrey C. Lagarias, \emph{On the Normality of Arithmetical Constants}, arXiv:math/0101055v2 (2002), Introduction and Section 2, Definition 2.2. \url{https://arxiv.org/pdf/math/0101055}.
\end{description}
